package com.bank.deploy;

// A deployable version. errorRate simulates how healthy it is in production.
public class Version {
    private final String tag;
    private final double errorRate; // 0.0 = perfect, 1.0 = fails every request

    public Version(String tag, double errorRate) {
        this.tag = tag;
        this.errorRate = errorRate;
    }
    public String getTag()       { return tag; }
    public double getErrorRate() { return errorRate; }
}
