package com.bank.deploy;

// Splits traffic between old and new by a weight (0..100 % to new).
public class Router {
    private int percentToNew;

    public Router(int percentToNew) { this.percentToNew = percentToNew; }

    public void setPercentToNew(int percent) { this.percentToNew = percent; }
    public int getPercentToNew() { return percentToNew; }

    // Decide which version serves a request given a 0..99 bucket.
    public Version route(int bucket, Version oldV, Version newV) {
        return bucket < percentToNew ? newV : oldV;
    }
}
