package com.bank.deploy;

import java.util.logging.Logger;

// Gradually shifts instances from old to new in steps (no downtime).
public class RollingUpdate {
    private static final Logger log = Logger.getLogger(RollingUpdate.class.getName());

    public void run(Router router, int stepPercent) {
        log.info("Rolling update: shifting instances gradually");
        for (int pct = stepPercent; pct <= 100; pct += stepPercent) {
            router.setPercentToNew(pct);
            int finalPct = pct;
            log.info(() -> "  rolled: " + (100 - finalPct) + "% old / " + finalPct + "% new (both live)");
        }
        log.info("Rolling update complete: 100% new");
    }
}
