package com.bank.deploy;

import java.util.logging.Logger;

// Deploys+tests green, then flips ALL traffic at once; instant rollback.
public class BlueGreen {
    private static final Logger log = Logger.getLogger(BlueGreen.class.getName());

    public void switchToGreen(Router router, Version green) {
        log.info(() -> "Blue-green: green " + green.getTag() + " deployed, running smoke tests");
        if (green.getErrorRate() > 0.1) {
            log.severe("Green failed smoke tests -> staying on blue (no switch)");
            return;
        }
        router.setPercentToNew(100); // instant flip
        log.info("Blue-green: flipped 100% traffic to green");
    }

    public void rollback(Router router) {
        router.setPercentToNew(0); // instant flip back
        log.warning("Blue-green: flipped back to blue instantly");
    }
}
