package com.bank.deploy;

import java.util.logging.Logger;

// Ramps traffic to new version, aborting if its error rate is too high.
public class Canary {
    private static final Logger log = Logger.getLogger(Canary.class.getName());
    private static final double MAX_ERROR = 0.05; // abort threshold

    public boolean run(Router router, Version newV, int[] steps) {
        for (int weight : steps) {
            router.setPercentToNew(weight);
            double observed = newV.getErrorRate();
            log.info(() -> "Canary at " + weight + "% -> observed error rate " + observed);
            if (observed > MAX_ERROR) {
                router.setPercentToNew(0);
                log.severe("Canary error rate " + observed + " > " + MAX_ERROR + " -> ABORT, roll back to 0%");
                return false;
            }
        }
        log.info("Canary healthy at every step -> promoted to 100%");
        return true;
    }
}
