package com.bank.deploy;

import java.util.logging.*;

public class DeployStrategiesDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DeployLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(DeployStrategiesDemo.class.getName());

        Version oldV = new Version("transfer-service:1.0.0", 0.01);

        log.info("=== ROLLING UPDATE ===");
        new RollingUpdate().run(new Router(0), 25);

        log.info("=== BLUE-GREEN (healthy green) ===");
        BlueGreen bg = new BlueGreen();
        Router bgRouter = new Router(0);
        bg.switchToGreen(bgRouter, new Version("transfer-service:2.0.0", 0.02));

        log.info("=== CANARY (healthy new version) ===");
        new Canary().run(new Router(0), new Version("transfer-service:1.1.0", 0.02),
                new int[]{5, 25, 50, 100});

        log.info("=== CANARY (bad new version -> abort) ===");
        new Canary().run(new Router(0), new Version("fraud-rules:bad", 0.30),
                new int[]{5, 25, 50, 100});
    }
}

